  /* SPEC §5 "Mesh ghosts" (T9.1): the world bounding sphere of every object. An object whose mesh has
   * no triangles keeps the helper's empty sphere (centre (0, 0, 0), radius 0). */
  for (KernelPainterlyObject &object : objects) {
    const KernelPainterlyMesh &mesh = meshes[object.mesh];
    if (mesh.num_tris > 0) {
      painterly_mesh_ghost_bounding_sphere(object.tfm,
                                           tri_vertices.data() + 9 * size_t(mesh.tri_offset),
                                           mesh.num_tris,
                                           &object.bound_center,
                                           &object.bound_radius);
    }
  }

